def _w(ctx, text):
    out = ctx.actions.declare_file(ctx.label.name + ".txt")
    ctx.actions.write(out, text)
    return [DefaultInfo(files = depset([out]))]

def _has_impl(ctx):
    return _w(ctx, "has=" + repr(ctx.target_platform_has_constraint(ctx.attr.cv[platform_common.ConstraintValueInfo])) + "\n")

has = rule(implementation = _has_impl, attrs = {"cv": attr.label(providers = [platform_common.ConstraintValueInfo])})

def _provided_impl(ctx):
    d = ctx.attr.dep
    return _w(ctx, "platform=%s\ncv=%s\ncs=%s\n" % (platform_common.PlatformInfo in d, platform_common.ConstraintValueInfo in d, platform_common.ConstraintSettingInfo in d))

provided = rule(implementation = _provided_impl, attrs = {"dep": attr.label()})

def _plat_label_impl(ctx):
    return _w(ctx, "label=" + str(ctx.attr.dep[platform_common.PlatformInfo].label) + "\n")

plat_label = rule(implementation = _plat_label_impl, attrs = {"dep": attr.label()})

def _plat_constraints_impl(ctx):
    c = ctx.attr.dep[platform_common.PlatformInfo].constraints
    cv = ctx.attr.cv[platform_common.ConstraintValueInfo]
    cs = cv.constraint
    got = c.get(cs)
    return _w(ctx, "has=%s\nhas_value=%s\nget=%s\nsettings=%s\n" % (c.has(cs), c.has_constraint_value(cv), got.label if got else None, sorted([str(s.label) for s in c.constraint_settings])))

plat_constraints = rule(implementation = _plat_constraints_impl, attrs = {"dep": attr.label(), "cv": attr.label()})

def _cv_impl(ctx):
    cv = ctx.attr.dep[platform_common.ConstraintValueInfo]
    return _w(ctx, "label=%s\nsetting=%s\n" % (cv.label, cv.constraint.label))

cv_info = rule(implementation = _cv_impl, attrs = {"dep": attr.label()})

def _cs_impl(ctx):
    cs = ctx.attr.dep[platform_common.ConstraintSettingInfo]
    return _w(ctx, "has_default=%s\n" % cs.has_default_constraint_value)

cs_has_default = rule(implementation = _cs_impl, attrs = {"dep": attr.label()})

def _cs_full_impl(ctx):
    cs = ctx.attr.dep[platform_common.ConstraintSettingInfo]
    d = cs.default_constraint_value
    return _w(ctx, "label=%s\ndefault=%s\n" % (cs.label, d.label if d else None))

cs_full = rule(implementation = _cs_full_impl, attrs = {"dep": attr.label()})

def _ctor_impl(ctx):
    platform_common.PlatformInfo()
    return []

ctor = rule(implementation = _ctor_impl)

