go_config(
    name = "go_config",
    amd64 = select({
        "//go/constraints/amd64:v2": "v2",
        "//go/constraints/amd64:v3": "v3",
        "//go/constraints/amd64:v4": "v4",
        # The default is v1.
        "//conditions:default": None,
    }),
    arm = select({
        "//go/constraints/arm:5": "5",
        "//go/constraints/arm:6": "6",
        "//go/constraints/arm:7": "7",
        "//conditions:default": None,
    }),
    debug = select({
        "//go/private:is_compilation_mode_dbg": "//go/private:always_true",
        "//conditions:default": "//go/config:debug",
    }),
    force_pic = select({
        "//go/private:force_pic": True,
        "//conditions:default": False,
    }),
    stamp = select({
        "//go/private:stamp": True,
        "//conditions:default": False,
    }),
    strip = select({
        "//go/private:is_strip_always": True,
        "//go/private:is_strip_sometimes_fastbuild": True,
        "//conditions:default": False,
    }),
)
platform(name = "linux_amd64", constraint_values = ["//os:linux", "//cpu:x86_64"])
platform(name = "linux_amd64_v1", parents = [":linux_amd64"], constraint_values = ["//go/constraints/amd64:v1"])
