platform(name = "linux_amd64_v4", parents = [":linux_amd64"], constraint_values = ["//go/constraints/amd64:v4"])
platform(name = "linux_arm_5", constraint_values = ["//os:linux", "//cpu:arm64", "//go/constraints/arm:5"])
platform(name = "linux_arm_6", constraint_values = ["//os:linux", "//cpu:arm64", "//go/constraints/arm:6"])
platform(name = "linux_arm_7", constraint_values = ["//os:linux", "//cpu:arm64", "//go/constraints/arm:7"])
platform(name = "both_v2_arm6", constraint_values = ["//go/constraints/amd64:v2", "//go/constraints/arm:6"])

